descriptor.templateCss:
.vent-demo-root h2,.vent-demo-root h3{font-weight:700;line-height:normal}
.vent-demo-root p{line-height:normal}
.vent-demo-root :where(b,strong){font-weight:700}
.vent-demo-root :where(table,th,td){font-family:inherit;font-size:inherit}
:root,.vent-demo-root{--bg:#0c1622;--panel:#152737;--input:#203747;--border:#345163;--text:#edf5f9;--sub:#aec4d1;--teal:#00d4e0;--ok:#2ee6a8;--warn:#ffc857;--danger:#ff3b42;--off:#607d8b;font-family:Arial,"Helvetica Neue",sans-serif;color:var(--text);background:var(--bg)}
*{box-sizing:border-box}
.loading{color:var(--sub)}
.vent-header,.panel,.kpi{background:var(--panel);border:1px solid var(--border);border-radius:6px}
.vent-header{overflow:hidden}
.vent-header__top{height:48px;display:flex;align-items:center;gap:10px;padding:0 16px;border-bottom:1px solid var(--border)}
.vent-header__title{font-size:18px;color:var(--teal)}
.vent-header__scope{margin-left:auto;color:var(--sub);white-space:nowrap}
.demo-badge{padding:4px 8px;border:1px solid var(--warn);border-radius:4px;color:var(--warn);font-size:12px}
.state-tabs{min-height:48px;display:flex;align-items:stretch;overflow-x:auto;background:var(--bg)}
.state-tabs a{display:flex;align-items:center;min-height:44px;padding:8px 14px;border-bottom:2px solid transparent;color:var(--text);text-decoration:none;white-space:nowrap}
.state-tabs a.active{color:var(--teal);border-bottom-color:var(--teal)}
.view{display:grid;gap:10px;margin-top:10px}
.kpi-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
.kpi{min-height:112px;padding:12px}
.kpi__head{display:flex;align-items:center;gap:8px;color:var(--sub);font-size:13px}
.kpi__icon{display:grid;place-items:center;width:24px;height:24px;border:1px solid var(--teal);border-radius:6px;color:var(--teal)}
.kpi__value{display:block;margin:9px 0 4px;font-size:26px;font-weight:600;font-variant-numeric:tabular-nums}
.kpi__quality,.muted{color:var(--sub);font-size:12px}
.quality-STALE,.status-WARNING{color:var(--warn)}
.quality-OFFLINE,.status-MAJOR,.status-FAULT{color:var(--danger)}
.quality-UNKNOWN,.status-UNKNOWN{color:var(--sub)}
.quality-CURRENT,.status-ONLINE,.status-RUNNING{color:var(--ok)}
.overview-grid{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(300px,.85fr);gap:10px}
.overview-context{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.2fr);gap:16px;align-items:center;margin-top:16px;padding-top:12px;border-top:1px solid var(--border)}
.overview-context__copy{min-width:0}.overview-context__copy h3{margin:6px 0;font-size:19px;line-height:1.35;font-weight:600}.overview-context__copy>p:not(.eyebrow){color:var(--sub);font-size:12px;line-height:1.6;margin:7px 0}.barn-illustration{margin:0;min-width:0}.barn-illustration img{display:block;width:100%;height:180px;object-fit:contain}.barn-illustration figcaption{color:var(--sub);font-size:9px;text-align:center;line-height:1.5;letter-spacing:.3px}
@media(max-width:700px){.overview-context{grid-template-columns:minmax(0,1fr);gap:8px}.overview-context__copy h3{font-size:17px}.barn-illustration img{height:170px}}
.panel{padding:14px;min-width:0}
.panel__head{display:flex;justify-content:space-between;gap:12px;align-items:start;padding-bottom:10px;border-bottom:1px solid var(--border)}
.panel__head h2{margin:0;font-size:17px}
.panel__head p{margin:3px 0 0;color:var(--sub);font-size:12px}
.barn-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:9px;margin-top:12px}
.barn-card{appearance:none;min-height:108px;padding:11px;text-align:left;background:var(--bg);color:var(--text);border:1px solid var(--border);border-radius:6px;cursor:pointer}
.barn-card:hover,.barn-card:focus-visible{outline:2px solid var(--teal);outline-offset:-2px}
.barn-card b{display:block;font-size:16px;margin-bottom:9px}
.barn-card span{display:block;font-size:12px;line-height:1.55}
.alarm-list{display:grid;gap:8px;margin-top:12px}
.alarm-mini{padding:9px;border-left:3px solid var(--warn);background:var(--bg)}
.alarm-mini.MAJOR{border-color:var(--danger)}
.alarm-mini b,.alarm-mini small{display:block}
.alarm-mini small{margin-top:4px;color:var(--sub)}
.detail-layout{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(270px,.7fr);gap:10px}
.synoptic{overflow-x:auto;overscroll-behavior-x:contain}
.synoptic svg{display:block;min-width:760px;width:100%;height:auto}
.pipe{fill:none;stroke:#86a9bc;stroke-width:3}
.zone{fill:var(--bg);stroke:var(--border);stroke-width:2}
.fan circle,.pump rect,.louver rect{fill:var(--input);stroke:var(--ok);stroke-width:3}
.fan.UNKNOWN circle,.pump.UNKNOWN rect{stroke:var(--sub);stroke-dasharray:5}
.fan-blades{transform-box:fill-box;transform-origin:center}.fan-blades path{fill:#86a9bc;stroke:var(--panel);stroke-width:1}.fan-hub{fill:var(--text);stroke:var(--teal);stroke-width:2}.fan.RUNNING.quality-CURRENT.connectivity-ONLINE .fan-blades{animation:vent-fan-spin 3.6s linear infinite}@keyframes vent-fan-spin{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}
.svg-label{fill:var(--text);font-size:13px;text-anchor:middle}
.svg-sub{fill:var(--sub);font-size:11px;text-anchor:middle}
.equipment-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;margin-top:10px}
.equipment-card{padding:9px;background:var(--bg);border:1px solid var(--border);border-radius:5px}
.equipment-card small,.equipment-card b{display:block}
.equipment-card small{color:var(--sub);margin-bottom:4px}
.controller-summary{display:grid;gap:9px}
.summary-row{display:flex;justify-content:space-between;gap:12px;padding:10px;background:var(--bg);border:1px solid var(--border);border-radius:5px}
.summary-row span{color:var(--sub)}
.notice{padding:10px;border-left:3px solid var(--warn);background:rgba(255,200,87,.08);color:var(--sub);font-size:12px}
.chart-wrap{overflow-x:auto}
.chart{display:block;min-width:720px;width:100%;height:310px}
.chart .grid{stroke:var(--border);stroke-width:1}
.chart text{fill:var(--sub);font-size:11px}
.chart .inside{fill:none;stroke:var(--teal);stroke-width:3}
.chart .outside{fill:none;stroke:var(--warn);stroke-width:3}
.chart .humidity{fill:none;stroke:#6aa9ff;stroke-width:3}
.legend{display:flex;gap:16px;flex-wrap:wrap;color:var(--sub);font-size:12px}
.legend i{display:inline-block;width:14px;height:3px;margin-right:5px;vertical-align:middle}
.axis-label{font-size:10px}.axis-left{text-anchor:end}.axis-right{text-anchor:start}.chart-point{stroke:var(--panel);stroke-width:2;cursor:help}.chart-sample:focus{outline:none}.chart-sample:focus .chart-point,.chart-sample:hover .chart-point{stroke:var(--text);stroke-width:2.5}.chart-sample:focus .chart-point{r:6}
.table-wrap{overflow-x:auto}
.data-table{width:100%;min-width:720px;border-collapse:collapse}
.data-table th,.data-table td{padding:12px;text-align:left;border-bottom:1px solid var(--border)}
.data-table th{color:var(--teal);font-size:12px}
.pill{display:inline-block;padding:3px 7px;border:1px solid currentColor;border-radius:4px;font-size:11px;font-weight:700}
.footer{display:flex;justify-content:space-between;gap:10px;color:var(--sub);font-size:12px;padding:2px 4px}
.error{padding:18px;border:1px solid var(--danger);color:var(--danger)}
.local-filter{display:flex;align-items:center;gap:8px;margin-top:10px;color:var(--sub);font-size:12px}.local-filter input{width:min(280px,100%);padding:7px 9px;border:1px solid var(--border);border-radius:4px;background:var(--bg);color:var(--text);font:inherit}.local-filter input::placeholder{color:#7990a0}.local-filter input:focus-visible,.settings-index a:focus-visible,.text-link:focus-visible{outline:2px solid var(--teal);outline-offset:2px}.filter-empty{margin:12px 0 0;color:var(--sub);font-size:13px}.eyebrow{margin:0 0 5px!important;color:var(--teal)!important;font-size:11px!important;font-weight:700;letter-spacing:.55px}.barn-context-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin:14px 0}.barn-context-grid>div{padding:10px;background:var(--bg);border:1px solid var(--border);border-radius:5px}.barn-context-grid small,.barn-context-grid b{display:block}.barn-context-grid small{margin-bottom:5px;color:var(--sub);font-size:11px}
.context-links{display:flex;flex-wrap:wrap;gap:14px}.view>[data-filter-list="settings"]{display:grid;gap:10px;min-width:0}
@media(max-width:1100px){.kpi-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.overview-grid,.detail-layout{grid-template-columns:1fr}}
@media(max-width:700px){.vent-header__top{padding:0 10px}.vent-header__title{font-size:16px}.vent-header__scope{display:none}.state-tabs a{padding:7px 10px;font-size:13px}.kpi-grid{grid-template-columns:1fr;gap:8px}.kpi{min-height:96px}.overview-grid{display:block}.overview-grid>.panel+.panel{margin-top:8px}.panel{padding:11px}.barn-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.equipment-grid{grid-template-columns:1fr}.footer{flex-direction:column}}
.barn-card em{display:inline-block;margin-left:4px;padding:1px 4px;border:1px solid var(--warn);border-radius:3px;color:var(--warn);font-size:9px;font-style:normal;vertical-align:2px}
.detail-main{align-self:start}
.controller-panel{align-self:stretch}
.controller-summary{gap:7px}
.subsection-title{margin:14px 0 7px;padding-top:11px;border-top:1px solid var(--border);font-size:13px;color:var(--teal);text-transform:uppercase;letter-spacing:.5px}
.secondary-metrics{display:grid;gap:7px}
.secondary-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:9px 10px;background:var(--bg);border:1px solid var(--border);border-radius:5px}
.secondary-row>span{color:var(--sub)}
.secondary-row small{display:block;margin-top:2px;font-size:10px}
.secondary-row b{font-variant-numeric:tabular-nums}
.compact-notice{margin-top:9px}
.text-link{display:inline-block;margin-top:11px;color:var(--teal);text-decoration:none}
.text-link:hover{text-decoration:underline}
.equipment-grid{grid-template-columns:repeat(4,minmax(0,1fr));gap:7px}
.synoptic svg{min-width:760px}
.chart .perceived{fill:none;stroke:#ff8fcf;stroke-width:3}
.demo-limit{margin:0;padding:2px 4px;color:var(--sub);font-size:11px}
.barn-card em.identity-PILOT{border-color:var(--teal);color:var(--teal)}
.barn-card em.identity-SYNTHETIC{border-color:var(--sub);color:var(--sub)}
.fan.STOPPED circle{stroke:var(--off)}
.louver.quality-STALE rect{stroke:var(--warn)}
.louver.quality-OFFLINE rect{stroke:var(--danger)}
.louver.quality-UNKNOWN rect{stroke:var(--sub);stroke-dasharray:5}
.svg-sub.state-RUNNING{fill:var(--ok)}
.status-STOPPED{color:var(--text)}
.synoptic,.chart-wrap,.table-wrap{scrollbar-color:var(--border) transparent}
.fan.NOT_CONFIGURED{opacity:.45}.fan.NOT_CONFIGURED circle{stroke:var(--off);stroke-dasharray:3 4}.svg-sub.state-NOT_CONFIGURED{fill:var(--sub);font-size:10px}.status-NOT_CONFIGURED{color:var(--sub);font-weight:600}.equipment-card.state-card-NOT_CONFIGURED{opacity:.6;border-style:dashed}.system-flags{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:10px 0 2px}.system-flag{display:flex;align-items:center;gap:8px;padding:6px 10px;background:var(--bg);border:1px solid var(--border);border-radius:5px}.system-flag small{color:var(--sub);font-size:12px}.system-flag b{font-size:13px}.flag-ACTIVE{border-color:var(--danger)}.flag-ACTIVE b{color:var(--danger)}.flag-NORMAL b{color:var(--ok)}.flag-UNKNOWN b,.flag-NOT_CONFIGURED b{color:var(--sub)}.system-flag-note{color:var(--sub);font-size:11px}.operation-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px}.operation-cell{padding:8px 10px;background:var(--bg);border:1px solid var(--border);border-radius:5px}.operation-cell>small{display:block;color:var(--sub);font-size:12px;margin-bottom:3px}.operation-cell b small{color:var(--sub);font-weight:400}.operation-cell b{font-variant-numeric:tabular-nums}.derived-tag{display:inline-block;margin-left:4px;padding:0 4px;border:1px solid var(--border);border-radius:3px;color:var(--sub);font-size:9px;font-style:normal;vertical-align:1px}.source-tag{display:inline-block;margin-left:6px;padding:0 5px;border:1px solid currentColor;border-radius:3px;font-size:10px;font-style:normal;font-weight:700;vertical-align:1px}.source-PLC{color:var(--teal)}.source-PLATFORM{color:var(--warn)}.settings-index{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.settings-index a{padding:6px 10px;border:1px solid var(--border);border-radius:5px;background:var(--bg);color:var(--text);text-decoration:none;font-size:13px}.settings-index a small{color:var(--sub);margin-left:4px}.settings-index a:hover{border-color:var(--teal)}.settings-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px 14px;margin-top:10px}.settings-row{display:grid;grid-template-columns:minmax(0,1fr) auto 44px;align-items:center;gap:10px;padding:7px 10px;background:var(--bg);border:1px solid var(--border);border-radius:5px}.settings-row span:first-child{color:var(--sub)}.settings-row small{color:var(--sub)}.setting-value{font-variant-numeric:tabular-nums}.settings-matrix{margin-top:10px;min-width:640px}.settings-matrix th small{color:var(--sub);font-weight:400}.settings-matrix td,.settings-matrix th{padding:8px 10px;white-space:nowrap}.settings-note{margin:10px 0 0;color:var(--warn);font-size:12px}.air-water .table-wrap{margin-top:8px}.status-NORMAL{color:var(--ok)}.status-ACTIVE{color:var(--danger)}
@media(max-width:1100px){.operation-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.equipment-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.controller-panel{align-self:start}}
@media(max-width:700px){.settings-list{grid-template-columns:1fr}.operation-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.equipment-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.secondary-row{padding:8px}.demo-limit{padding:3px 1px}}
@media(max-width:700px){.local-filter{align-items:stretch;flex-direction:column}.local-filter input{width:100%}.barn-context-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(prefers-reduced-motion:reduce){.fan.RUNNING.quality-CURRENT.connectivity-ONLINE .fan-blades{animation:none}}
.vent-demo-root{display:block;height:100%;overflow-y:auto;overflow-x:hidden;padding:12px;background:var(--bg);font-size:14px;line-height:normal}
.vent-demo-root>.view:first-of-type,.vent-demo-root .vent-header+.view{margin-top:10px}
.vent-demo-root :where(h2,h3,p){letter-spacing:normal}
.vent-demo-root a{border-bottom:0;text-decoration:none}
.vent-demo-root .state-tabs a{border-bottom:2px solid transparent}
.vent-demo-root .state-tabs a.active{border-bottom-color:var(--teal)}
.vent-demo-root :where(button){font:inherit}
.vent-demo-root .vent-header__top{padding-right:64px}
@media(max-width:700px){.vent-demo-root{padding:8px}}

