self.onInit = function () {
  var __vent = {};
  __vent.VentilationAssets = {barnIllustration: "data:image/webp;base64,"};
// SINH TỰ ĐỘNG bởi tools/build_contract_module.py từ Data Contract v0.3 + contract_v0.3_decisions.json.
